export const rules = [
  { id: "r.edge_source", label: "Every relationship records how it is known", kind: "provenance", statement: "An edge carries its source system, the time it was last confirmed, and whether it was declared, discovered, inferred or measured. A map built from forms decays; a map built from feeds is refreshed by the act of being connected." },
  { id: "r.edge_age", label: "Edges show their age", kind: "provenance", statement: "Confidence and staleness are displayed, not hidden. A user who can see that an edge was last confirmed eleven months ago can judge it. A clean diagram with no provenance will be trusted and then be wrong." },
  { id: "r.declared_decays", label: "Declared is weaker than discovered", kind: "provenance", statement: "Where a declared edge and a discovered edge disagree, the discovered one wins and the disagreement is reported rather than silently resolved." },
  { id: "r.one_identity", label: "One physical thing, one node", kind: "provenance", statement: "The same asset appearing in several systems resolves to one node, with the source identifiers retained. Entity resolution is deterministic first and fuzzy second, with a human confirming anything below threshold." },
  { id: "r.reconcile", label: "Disagreement is a finding", kind: "provenance", statement: "Where systems of record disagree on existence, location or capacity, the gap is reported as a reconciliation finding rather than being averaged away." },
  { id: "r.capacity_three", label: "Keep installed, reserved and drawn apart", kind: "capacity", statement: "Installed, reserved and actual draw are three different numbers. Conflating them is how an estate convinces itself it is full. Stranded capacity is the gap between reserved and drawn where the workload is not live." },
  { id: "r.derate", label: "Capacity is derated before it is offered", kind: "capacity", statement: "Published capacity is the derated figure after ambient, loading and redundancy are accounted for, never the nameplate." },
  { id: "r.binding_constraint", label: "Always name the binding constraint", kind: "capacity", statement: "A capacity answer states which resource runs out first - power, cooling, space, network or water. A number without its constraint cannot be acted on." },
  { id: "r.coincident", label: "Compute headroom from coincident peak", kind: "capacity", statement: "Headroom is computed against coincident peak, not average. AI training clusters ramp together, so diversity assumptions drawn from enterprise colocation understate demand." },
  { id: "r.reservation_hygiene", label: "Reservations expire", kind: "capacity", statement: "A reservation with no draw after a stated period is flagged for review. Reservations that never expire are the commonest cause of stranded capacity." },
  { id: "r.actual_redundancy", label: "Designed redundancy is a document; actual redundancy is a query", kind: "resilience", statement: "Redundancy state is computed from live breaker and valve positions joined to cluster topology, not read from the design intent. The two diverge quietly over years." },
  { id: "r.dual_cord", label: "Verify dual cording, do not assume it", kind: "resilience", statement: "Dual-corded status is confirmed from measurement or survey. Records of it are wrong often enough that assuming them is a resilience risk in itself." },
  { id: "r.shared_route", label: "Physical route is part of the dependency", kind: "resilience", statement: "Two paths that share a duct, a riser or a room are not independent, whatever the single line diagram says." },
  { id: "r.failure_domain", label: "Independence is proved, not declared", kind: "resilience", statement: "Services described as independent are tested for shared failure domains across power, cooling, network and platform." },
  { id: "r.window_sequence", label: "Sequence work so nothing drops below its requirement", kind: "resilience", statement: "A maintenance plan is ordered so that no step takes a critical service below its required redundancy. The sequence is computed, not judged." },
  { id: "r.read_only_ot", label: "Read-only toward operational technology", kind: "control", statement: "The model never writes to a BMS, EPMS, SCADA or any life-safety system. A twin or an agent may propose a setpoint change; a person applies it. Creating a ticket is the one permitted write." },
  { id: "r.engines_compute", label: "Engines compute, the model explains", kind: "control", statement: "No figure shown to a user originates from a language model. Deterministic engines produce every number; natural language is used to describe, not to calculate." },
  { id: "r.advisory", label: "Recommendations are advisory and recorded", kind: "control", statement: "Every recommendation states its basis, is applied by a person, and the outcome is written back so the model can be calibrated against what actually happened." },
  { id: "r.pue_measured", label: "A design PUE is not an operating PUE", kind: "sustainability", statement: "PUE is a design target until measured in operation, and is bounded by site design wet-bulb and the cooling technology. Quoting a target as an outcome is the commonest misstatement in this sector." },
  { id: "r.matching_basis", label: "Always state the matching basis", kind: "sustainability", statement: "A renewable percentage is published with its basis - annual, monthly, hourly or unbundled certificates. The same number means different things under each." },
  { id: "r.water_power_trade", label: "Show water and power together", kind: "sustainability", statement: "Any cooling comparison shows the water and the energy position together. Presenting a PUE improvement without its water consequence misstates the choice." },
  { id: "r.attribution_rule", label: "Attribution states its allocation basis", kind: "sustainability", statement: "Energy or emissions attributed to a service carry the rule used to apportion shared quantities. Without it the figure cannot be audited or reproduced." },
  { id: "r.scope_labels", label: "Label the scope and the method", kind: "sustainability", statement: "Every emissions figure states its scope, its boundary and whether Scope 2 is location or market based." },
  { id: "r.alarm_priority", label: "Do not trust configured alarm priority", kind: "operations", statement: "Priority as set by the installer is usually meaningless. Severity is re-derived from the consequence of the affected asset, computed by traversal." },
  { id: "r.standing_alarms", label: "Separate standing from actionable", kind: "operations", statement: "An alarm that has stood for weeks carries no information. Standing, chattering and actionable alarms are counted separately and the first job on any estate is rationalisation, not smarter alerting." },
  { id: "r.correlate_topology", label: "Correlate along the chain, not just in time", kind: "operations", statement: "Alarms on assets in one power or cooling chain are one situation. Temporal clustering alone groups unrelated events that happened to coincide." },
  { id: "r.cause_hypothesis", label: "A cause is a hypothesis until proved", kind: "operations", statement: "Suggested causes are presented ranked, with their evidence, and never as a determination." },
  { id: "r.impact_first", label: "Lead with impact, not with the alarm", kind: "operations", statement: "An operator is shown what is affected and who owns it before being shown which device raised the alarm." },
  { id: "r.criticality_human", label: "Criticality and ownership are captured, not inferred", kind: "modelling", statement: "Service criticality and ownership are judgement. They are captured from the organisation and reviewed, never derived from telemetry." },
  { id: "r.usage_decides", label: "Usage decides liveness", kind: "modelling", statement: "Whether an application is alive is decided by an observed usage signal. Where no signal exists, the model reports that it cannot judge rather than assuming the application is in use." },
  { id: "r.no_silent_estimate", label: "Never substitute an estimate for a measurement", kind: "modelling", statement: "A derived or benchmarked value is labelled as such. It is never shown in the same form as a measured one." },
  { id: "r.units_explicit", label: "Units and basis travel with the number", kind: "modelling", statement: "Every quantity carries its unit, and every capacity states whether it is IT load or total intake." },
  { id: "r.time_basis", label: "State the period and the as-of time", kind: "modelling", statement: "Every aggregate states the period it covers and the time it was computed. Estates change faster than reports are read." },
  { id: "r.model_calibration", label: "Calibrate the twin against outcome", kind: "modelling", statement: "Simulation results are compared with what actually happened, and the model is adjusted. An uncalibrated twin diverges silently from the estate it claims to represent." },
  { id: "r.fit_quality", label: "Report the quality of a fit", kind: "modelling", statement: "A trend or forecast is published with its goodness of fit and its horizon, so a weak projection is visibly weak." },
  { id: "r.used_daily", label: "A map maintained only for reporting rots", kind: "modelling", statement: "The model is the thing an operator looks at during an incident and the thing a planner uses to approve a deployment. Daily use is what keeps it true." },
];

const classById = new Map(classes.map((c) => [c.id, c]));
export const getClass = (id) => classById.get(id);

/** Classes grouped by domain, for a coverage map. */
export const classesByDomain = () =>
  classes.reduce((acc, c) => {
    (acc[c.domain] = acc[c.domain] || []).push(c);
    return acc;
  }, {});

/** Direct children of a class. */
export const childrenOf = (id) => classes.filter((c) => c.parent === id);

/** Attributes declared on a class. */
export const attributesOf = (id) => attributes.filter((a) => a.classId === id);

/** Headline coverage figures. */
export const coverage = () => ({
  domains: domains.length,
  classes: classes.length,
  relations: relations.length,
  attributes: attributes.length,
  enumerations: enumerations.length,
  metrics: metrics.length,
  paths: paths.length,
  rules: rules.length,
});

